package com.example.rokidgeminisecretary;
import android.content.*;import android.util.AtomicFile;import org.json.*;import java.io.*;import java.nio.charset.StandardCharsets;
/** Local encrypted reading and correction history. Original answer is immutable. */
final class ReadingHistory {
 static AtomicFile file(Context c){return new AtomicFile(new File(c.getFilesDir(),"reading-history-v1.gcm"));}
 static JSONArray read(Context c)throws Exception{AtomicFile f=file(c);if(!f.getBaseFile().exists()&&!new File(f.getBaseFile()+".bak").exists())return new JSONArray();byte[] bytes=f.readFully();if(bytes.length>6500000)throw new IOException("読み取り履歴が大きすぎます");JSONArray rows=new JSONArray(new String(DeviceSecrets.photos().decrypt(bytes),StandardCharsets.UTF_8));if(rows.length()>100)throw new IOException("読み取り履歴の件数が不正です");return rows;}
 static void write(Context c,JSONArray rows)throws Exception{byte[] bytes=rows.toString().getBytes(StandardCharsets.UTF_8);if(bytes.length>6000000)throw new IOException("読み取り履歴の容量上限です。既存データは保持しています");AtomicFile f=file(c);FileOutputStream out=null;try{out=f.startWrite();out.write(DeviceSecrets.photos().encrypt(bytes));f.finishWrite(out);}catch(Exception e){if(out!=null)f.failWrite(out);throw e;}}
 static synchronized void observe(Context c,JSONObject input)throws Exception{JSONObject value=ImageReferenceSummary.checked(input);value.remove("selectedAt");String id=RecorderPhotoStore.hash((value.getLong("at")+":"+value.getInt("imageCount")+":"+value.getString("question")+":"+value.getString("answer")).getBytes(StandardCharsets.UTF_8));JSONArray all=read(c);for(int i=0;i<all.length();i++)if(all.getJSONObject(i).getString("id").equals(id))return;value.put("id",id).put("revision",1).put("corrections",new JSONArray());all.put(value);JSONArray bounded=new JSONArray();long cutoff=System.currentTimeMillis()-90L*86400000;for(int i=Math.max(0,all.length()-100);i<all.length();i++)if(all.getJSONObject(i).optLong("at")>=cutoff)bounded.put(all.get(i));write(c,bounded);}
 static JSONArray list(Context c)throws Exception{JSONObject current=ImageReferenceStore.view(c);if(current.optBoolean("available"))observe(c,current);synchronized(ReadingHistory.class){JSONArray rows=read(c),out=new JSONArray();long cutoff=System.currentTimeMillis()-90L*86400000;for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);if(!row.optBoolean("deleted")&&row.optLong("at")>=cutoff)out.put(row);}return out;}}
 static synchronized JSONObject get(Context c,String id)throws Exception{JSONArray rows=read(c);for(int i=0;i<rows.length();i++)if(id.equals(rows.getJSONObject(i).getString("id"))&&!rows.getJSONObject(i).optBoolean("deleted"))return rows.getJSONObject(i);throw new IOException("読み取り記録がありません。履歴を開き直してください");}
 static synchronized JSONObject correct(Context c,String id,int revision,String changeId,String field,String before,String after)throws Exception{if(!changeId.matches("[a-f0-9-]{36}")||field==null||field.trim().isEmpty()||field.length()>120||before==null||before.length()>1200||after==null||after.trim().isEmpty()||after.length()>1200)throw new IOException("訂正内容を確認してください");JSONArray rows=read(c);for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);if(!id.equals(row.getString("id"))||row.optBoolean("deleted"))continue;JSONArray changes=row.getJSONArray("corrections");for(int j=0;j<changes.length();j++)if(changeId.equals(changes.getJSONObject(j).getString("id"))){JSONObject old=changes.getJSONObject(j);if(!field.trim().equals(old.getString("field"))||!before.equals(old.getString("before"))||!after.trim().equals(old.getString("after")))throw new IOException("同じ訂正IDの内容が異なります。開き直してください");return row;}if(row.getInt("revision")!=revision)throw new IOException("履歴が更新されています。開き直してください");if(!before.isEmpty()&&!row.getString("answer").contains(before))throw new IOException("変更前の文字が元の読み取りにありません。原文を確認してください");if(changes.length()>=20)throw new IOException("1件の訂正は20回までです");changes.put(new JSONObject().put("id",changeId).put("field",field.trim()).put("before",before).put("after",after.trim()).put("at",System.currentTimeMillis()));row.put("revision",revision+1);write(c,rows);return row;}throw new IOException("元の読み取り記録がありません");}
 static synchronized void delete(Context c,String id)throws Exception{JSONArray rows=read(c),next=new JSONArray();for(int i=0;i<rows.length();i++)if(!id.equals(rows.getJSONObject(i).optString("id")))next.put(rows.get(i));else next.put(new JSONObject().put("id",id).put("at",rows.getJSONObject(i).optLong("at")).put("deleted",true));write(c,next);}
 private ReadingHistory(){}
}
